"""Reviewed source links with original multilingual adaptations; no clinical validation claimed."""
import json
from pathlib import Path
langs=['pt','en','fr','it','es']
data={}
def add(slug,category,color,duration,source,kind,titles,subs,safety,evidence,steps):
 data[slug]={'category':category,'color':color,'duration':duration,'source':source,'kind':kind,'locales':{}}
 for i,l in enumerate(langs):
  data[slug]['locales'][l]={'title':titles[i],'subtitle':subs[i],'safety':safety[i],'evidence':evidence[i],'steps':[{'seconds':secs,'text':texts[i]} for secs,texts in steps]}
add('respiracao-suave','breathing','sage',5,{'name':'NHS · Breathing exercises for stress','url':'https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/breathing-exercises-for-stress/'},'breathing',
 ['Respiração sem pressa','Unhurried breathing','Respirer sans hâte','Respiro senza fretta','Respiración sin prisa'],
 ['Um ritmo confortável, sem prender o ar','A comfortable rhythm, without holding your breath','Un rythme confortable, sans retenir le souffle','Un ritmo comodo, senza trattenere il respiro','Un ritmo cómodo, sin retener el aire'],
 ['Respire sem forçar. Se sentir tontura ou desconforto, pare e volte ao seu ritmo natural.','Never force your breath. If you feel dizzy or uncomfortable, stop and return to natural breathing.','Ne forcez pas. En cas de vertige ou de gêne, arrêtez et retrouvez votre souffle naturel.','Non forzare. Se senti vertigini o disagio, fermati e torna al respiro naturale.','No fuerces la respiración. Si notas mareo o malestar, para y vuelve a tu ritmo natural.'],
 ['Adaptação da orientação do NHS para lidar com estresse. O ritmo visual é opcional; esta sessão não foi testada clinicamente.','Adapted from NHS stress guidance. The visual pace is optional; this session has not been clinically tested.','Adaptation des conseils du NHS pour le stress. Le rythme visuel est facultatif ; cette séance n’a pas été testée cliniquement.','Adattamento delle indicazioni NHS per lo stress. Il ritmo visivo è facoltativo; questa sessione non è stata testata clinicamente.','Adaptación de las recomendaciones del NHS para el estrés. El ritmo visual es opcional; esta sesión no se ha probado clínicamente.'],[
 (30,['Sente-se com apoio. Solte os ombros e deixe a respiração encontrar um ritmo confortável.','Sit with support. Release your shoulders and find a comfortable breathing rhythm.','Asseyez-vous avec un appui. Relâchez les épaules et trouvez un souffle confortable.','Siediti con un sostegno. Rilassa le spalle e trova un respiro comodo.','Siéntate con apoyo. Suelta los hombros y encuentra un ritmo cómodo.']),
 (90,['Inspire suavemente pelo nariz e solte pela boca, se for confortável. O círculo sugere cinco segundos em cada direção, sem pausas. Pode respirar mais rápido.','Breathe gently in through your nose and out through your mouth if comfortable. The circle suggests five seconds each way, with no holds. A faster pace is fine.','Inspirez doucement par le nez, expirez par la bouche si cela vous convient. Le cercle propose cinq secondes dans chaque sens, sans rétention. Un rythme plus rapide convient aussi.','Inspira piano dal naso ed espira dalla bocca, se comodo. Il cerchio propone cinque secondi per fase, senza pause. Puoi andare più veloce.','Inhala suavemente por la nariz y exhala por la boca si es cómodo. El círculo propone cinco segundos por fase, sin retenciones. Puedes ir más rápido.']),
 (150,['Continue sem encher os pulmões à força. Se a mente se distrair, perceba e volte à próxima respiração. Seu conforto guia o ritmo.','Continue without forcing a deep breath. When your mind wanders, notice and return to the next breath. Let comfort guide your pace.','Continuez sans forcer une inspiration profonde. Si l’esprit s’égare, revenez au souffle suivant. Votre confort guide le rythme.','Continua senza forzare respiri profondi. Se la mente vaga, torna al respiro successivo. Lascia che il comfort guidi il ritmo.','Continúa sin forzar respiraciones profundas. Si la mente se distrae, vuelve a la siguiente respiración. Tu comodidad guía el ritmo.']),
 (30,['Deixe a contagem. Respire naturalmente e perceba o apoio do corpo antes de terminar.','Let go of counting. Breathe naturally and notice your body’s support before finishing.','Laissez le comptage. Respirez naturellement et sentez vos appuis avant de terminer.','Lascia il conteggio. Respira naturalmente e senti il sostegno del corpo prima di finire.','Deja el conteo. Respira con naturalidad y nota el apoyo del cuerpo antes de terminar.'])])
add('relaxamento-progressivo','relaxation','peach',6,{'name':'VA Whole Health · Progressive Muscle Relaxation','url':'https://www.va.gov/WHOLEHEALTHLIBRARY/docs/Progressive-Muscle-Relaxation.pdf'},'pmr',
 ['Soltar a tensão do corpo','Release body tension','Relâcher les tensions','Sciogliere le tensioni','Soltar la tensión del cuerpo'],
 ['Relaxamento muscular progressivo, versão breve','Progressive muscle relaxation, a brief adaptation','Relaxation musculaire progressive, version brève','Rilassamento muscolare progressivo, versione breve','Relajación muscular progresiva, versión breve'],
 ['Use pouca força e respire normalmente. Pule áreas doloridas ou lesionadas. Com lesões importantes, espasmos ou problemas nas costas, consulte um profissional antes de contrair os músculos.','Use little effort and breathe normally. Skip painful or injured areas. With significant injuries, spasms or back problems, consult a clinician before tensing muscles.','Contractez peu et respirez normalement. Évitez les zones douloureuses ou blessées. En cas de blessure importante, spasmes ou problèmes de dos, consultez avant de contracter.','Usa poca forza e respira normalmente. Salta zone dolenti o lesionate. Con lesioni importanti, spasmi o problemi alla schiena, consulta un professionista prima di contrarre.','Usa poca fuerza y respira normalmente. Evita zonas doloridas o lesionadas. Con lesiones importantes, espasmos o problemas de espalda, consulta antes de contraer.'],
 ['A VA descreve esta técnica e pesquisas sobre relaxamento. Aqui usamos uma adaptação breve com quatro grupos musculares; não é o protocolo completo nem uma sessão clinicamente validada.','VA describes this technique and relaxation research. This brief four-group adaptation is neither the full protocol nor a clinically validated session.','La VA décrit cette technique et les recherches sur la relaxation. Cette adaptation à quatre groupes n’est ni le protocole complet ni une séance validée cliniquement.','La VA descrive la tecnica e la ricerca sul rilassamento. Questo adattamento a quattro gruppi non è il protocollo completo né una sessione validata clinicamente.','La VA describe la técnica y la investigación sobre relajación. Esta adaptación de cuatro grupos no es el protocolo completo ni una sesión validada clínicamente.'],[
 (40,['Acomode-se sentado ou deitado. Você vai contrair suavemente e depois soltar, sem segurar a respiração. Pode apenas imaginar o relaxamento.','Sit or lie comfortably. You will gently tense and release, without holding your breath. You may simply imagine the release instead.','Installez-vous assis ou allongé. Contractez doucement puis relâchez, sans retenir le souffle. Vous pouvez aussi imaginer le relâchement.','Siediti o sdraiati comodamente. Contrai piano e poi rilascia, senza trattenere il respiro. Puoi anche solo immaginare il rilascio.','Siéntate o túmbate cómodamente. Contrae suavemente y suelta, sin retener el aire. También puedes imaginar la relajación.']),
 (5,['Mãos: feche os dedos levemente.','Hands: gently curl your fingers.','Mains : repliez doucement les doigts.','Mani: chiudi delicatamente le dita.','Manos: cierra suavemente los dedos.']),
 (60,['Abra as mãos. Note a diferença entre tensão e repouso.','Open your hands. Notice the difference between tension and rest.','Ouvrez les mains. Notez la différence entre tension et repos.','Apri le mani. Nota la differenza tra tensione e riposo.','Abre las manos. Nota la diferencia entre tensión y reposo.']),
 (5,['Braços: dobre os cotovelos e contraia suavemente.','Arms: bend your elbows and tense gently.','Bras : pliez les coudes et contractez doucement.','Braccia: piega i gomiti e contrai delicatamente.','Brazos: dobla los codos y contrae suavemente.']),
 (60,['Solte os braços e deixe-os apoiados. Observe as sensações sem exigir relaxamento.','Release your arms and let them rest. Notice sensations without demanding relaxation.','Relâchez les bras sur leur appui. Observez sans exiger la détente.','Rilascia le braccia e appoggiale. Osserva senza pretendere il rilassamento.','Suelta los brazos y apóyalos. Observa sin exigir relajación.']),
 (5,['Ombros: eleve-os um pouco, sem forçar o pescoço.','Shoulders: lift them a little without straining your neck.','Épaules : soulevez-les un peu sans forcer le cou.','Spalle: sollevale poco, senza sforzare il collo.','Hombros: súbelos un poco, sin forzar el cuello.']),
 (60,['Deixe os ombros descerem e perceba o apoio do corpo.','Let your shoulders lower and notice the support beneath you.','Laissez descendre les épaules et sentez vos appuis.','Lascia scendere le spalle e senti il sostegno del corpo.','Deja caer los hombros y siente el apoyo del cuerpo.']),
 (5,['Pés: aponte os dedos suavemente, somente se confortável.','Feet: gently point your toes, only if comfortable.','Pieds : pointez doucement les orteils, seulement si cela convient.','Piedi: distendi piano le dita, solo se comodo.','Pies: apunta suavemente los dedos, solo si resulta cómodo.']),
 (60,['Solte os pés. Deixe as pernas repousarem. Respire naturalmente.','Release your feet. Let your legs rest. Breathe naturally.','Relâchez les pieds. Laissez reposer les jambes. Respirez naturellement.','Rilascia i piedi. Lascia riposare le gambe. Respira naturalmente.','Suelta los pies. Deja descansar las piernas. Respira con naturalidad.']),
 (60,['Observe o corpo inteiro. Leve alguns instantes para se mover e voltar ao ambiente.','Notice your whole body. Take a few moments to move and return to your surroundings.','Observez tout le corps. Prenez le temps de bouger et de retrouver votre environnement.','Osserva tutto il corpo. Prenditi il tempo di muoverti e tornare all’ambiente.','Observa todo el cuerpo. Tómate un tiempo para moverte y volver al entorno.'])])
add('atencao-presente','focus','lavender',5,{'name':'NCCIH · Meditation and Mindfulness','url':'https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety'},'mindfulness',
 ['Voltar ao presente','Return to the present','Revenir au présent','Tornare al presente','Volver al presente'],
 ['Atenção plena para quem está começando','Mindfulness for a gentle beginning','La pleine conscience pour débuter','Mindfulness per iniziare con dolcezza','Atención plena para empezar'],
 ['Mantenha os olhos abertos se preferir. Se a prática aumentar o mal-estar, pare e observe o ambiente ao seu redor.','Keep your eyes open if you prefer. If practice increases distress, stop and look around your surroundings.','Gardez les yeux ouverts si vous préférez. Si la pratique augmente le malaise, arrêtez et regardez autour de vous.','Tieni gli occhi aperti se preferisci. Se la pratica aumenta il disagio, fermati e osserva ciò che ti circonda.','Mantén los ojos abiertos si prefieres. Si la práctica aumenta el malestar, para y observa tu entorno.'],
 ['Programas de mindfulness têm estudos com benefícios para alguns sintomas, mas resultados e qualidade variam. Esta introdução de cinco minutos não equivale aos programas estudados.','Mindfulness programs have research showing benefits for some symptoms, but results and study quality vary. This five-minute introduction is not equivalent to the studied programs.','Des programmes de pleine conscience montrent des bénéfices pour certains symptômes, avec des résultats et une qualité variables. Cette introduction ne correspond pas aux programmes étudiés.','Programmi di mindfulness mostrano benefici per alcuni sintomi, ma risultati e qualità variano. Questa introduzione non equivale ai programmi studiati.','Hay estudios de programas de mindfulness con beneficios para algunos síntomas, pero los resultados y la calidad varían. Esta introducción no equivale a los programas estudiados.'],[
 (40,['Sente-se com conforto. Perceba os pés e o contato com a cadeira. Não há uma sensação certa para encontrar.','Sit comfortably. Notice your feet and contact with the chair. There is no right feeling to find.','Asseyez-vous confortablement. Sentez les pieds et le contact de la chaise. Il n’y a pas de sensation à réussir.','Siediti comodamente. Nota i piedi e il contatto con la sedia. Non c’è una sensazione giusta da trovare.','Siéntate cómodamente. Nota los pies y el contacto con la silla. No hay una sensación correcta que encontrar.']),
 (80,['Observe a respiração como ela está. Escolha uma sensação: o ar no nariz ou o movimento do abdômen. Não precisa mudar o ritmo.','Notice your breathing as it is. Choose one sensation: air at your nose or movement in your belly. No need to change the pace.','Observez le souffle tel qu’il est. Choisissez l’air au nez ou le mouvement du ventre. Ne changez pas le rythme.','Osserva il respiro così com’è. Scegli l’aria nel naso o il movimento dell’addome. Non cambiare il ritmo.','Observa la respiración tal como es. Elige el aire en la nariz o el movimiento del abdomen. No cambies el ritmo.']),
 (120,['Quando notar um pensamento, reconheça que estava pensando e volte à sensação escolhida. Cada retorno faz parte da prática.','When you notice a thought, acknowledge that you were thinking and return to your chosen sensation. Each return is part of practice.','Quand vous remarquez une pensée, reconnaissez-la puis revenez à la sensation choisie. Chaque retour fait partie de la pratique.','Quando noti un pensiero, riconoscilo e torna alla sensazione scelta. Ogni ritorno fa parte della pratica.','Cuando notes un pensamiento, reconócelo y vuelve a la sensación elegida. Cada regreso forma parte de la práctica.']),
 (60,['Amplie a atenção para os sons e o corpo. Olhe ao redor e escolha um próximo gesto com calma.','Widen your attention to sounds and your body. Look around and choose your next action calmly.','Élargissez l’attention aux sons et au corps. Regardez autour de vous et choisissez votre prochain geste calmement.','Allarga l’attenzione ai suoni e al corpo. Guarda intorno e scegli con calma il prossimo gesto.','Amplía la atención a los sonidos y al cuerpo. Mira alrededor y elige con calma tu siguiente acción.'])])
from expanded_meditations import expanded
data.update(expanded())
Path('exercise_seed.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
